 beam1=[{'id':'H-YO','score':2.0,'kind':'greeting'},{'id':'H-IO','score':.5,'kind':'input-output'},{'id':'H-Io','score':.1,'kind':'astronomy'}];kernel=sml.Kernel.CreateKernelInNewThread();assert not kernel.HadError();version=kernel.GetSoarKernelVersion();s1=soar(kernel,'t1',beam1);assert s1['selected']=='H-YO'
 selection1={'selection_event_id':'selection:io:t1','hypothesis_id':'H-YO','selected_at':'2026-01-01T10:00:03Z','known_later_to_be_wrong':True,'beam_ids':[h['id'] for h in beam1]};plan1={'plan_id':'PLAN-IO-T1','act':'greet','content':['yo'],'provenance':['H-YO','COMM-01 schema']};response1={'raw':'Yo!','plan_id':plan1['plan_id'],'added_content':[]};outcome1={'observation_id':'feedback:io:t1','raw':'No—I meant input/output.','grounding':'rejected-interpretation','repair':'select H-IO and apologize','immutable':True}
 t1={'observation':observation,'analyses':analyses,'retrieval':retrieval,'hypotheses':beam1,'ledger':hyp3['ranking_t1'],'beam':beam1,'soar':s1,'selection':selection1,'plan':plan1,'response':response1,'outcome':outcome1};t1_obs_hash=digest(observation);t1_sel_hash=digest(selection1)
 learned={'pattern_version_id':'Pattern_IO_001-v2','supersedes':'Pattern_IO_001-v1','added_episode':'feedback:io:t1','context':'computing-intent overrides surface greeting prior','effect':'input-output','old_pattern_mutated':False};episodes=training+[{'episode_id':'feedback:io:t1','speaker':'s-new','context':'computing-intent','form':'io','outcome':'input-output','repairs':'selection:io:t1'}]
 observation2={'observation_id':'obs:io:t2-heldout','raw':'io','speaker':'s-new','immutable':True,'context':'computing','heldout':True};beam2=[{'id':'H-IO','score':5.6,'kind':'input-output'},{'id':'H-Io','score':.8,'kind':'astronomy'},{'id':'H-YO','score':-.2,'kind':'greeting'}];s2=soar(kernel,'t2',beam2);kernel.Shutdown();assert s2['selected']=='H-IO';selection2={'selection_event_id':'selection:io:t2','hypothesis_id':'H-IO','selected_at':'2026-01-05T09:00:03Z','beam_ids':[h['id'] for h in beam2]};plan2={'plan_id':'PLAN-IO-T2','act':'clarify-computing-problem','content':['input-output'],'omitted':['yo','Io'],'provenance':['H-IO','Pattern_IO_001-v2','COMM-02 context-sensitive plan']};response2={'raw':'Is the input/output failing?','plan_id':plan2['plan_id'],'added_content':[]};outcome2={'observation_id':'feedback:io:t2','raw':'Yes, exactly.','grounding':'confirmed-for-exchange','correct':True,'immutable':True};t2={'observation':observation2,'analyses':analyses,'retrieval':retrieval,'hypotheses':beam2,'ledger':hyp3['ranking_t2'],'beam':beam2,'soar':s2,'selection':selection2,'plan':plan2,'response':response2,'outcome':outcome2}
 store=OUT/'episodes.parquet';pq.write_table(pa.Table.from_pylist(episodes),store,compression='zstd');t1_after_hashes={'observation':digest(t1['observation']),'selection':digest(t1['selection'])};trace=[{'stage':'t1-observation','value':observation},{'stage':'t1-analysis','value':analyses},{'stage':'t1-retrieval','value':retrieval},{'stage':'t1-selection','value':selection1},{'stage':'t1-response','value':response1},{'stage':'t1-outcome','value':outcome1},{'stage':'learning','value':learned},{'stage':'t2-observation','value':observation2},{'stage':'t2-selection','value':selection2},{'stage':'t2-response','value':response2},{'stage':'t2-outcome','value':outcome2}]
 vals={'raw_unknown_form_preserved':observation['raw']==observation2['raw']=='io' and observation['immutable'] and observation2['immutable'],'multiple_planes_and_candidates_active':not retrieval['collapse'] and len(beam1)==3 and len(beam2)==3,'yo_and_input_output_retrieved_together':all(x in json.dumps(retrieval) for x in ('form:yo','symbol:input-output')),'real_soar_selection_each_turn':all('1 rule fired' in s['run'] for s in (s1,s2)),'t1_wrong_selection_has_response_and_negative_outcome':s1['selected']=='H-YO' and response1['raw']=='Yo!' and outcome1['grounding']=='rejected-interpretation','explicit_correction_revises_without_mutation':learned['old_pattern_mutated'] is False and learned['added_episode']==outcome1['observation_id'],'t2_heldout_improves_interpretation':observation2['heldout'] and s2['selected']=='H-IO' and outcome2['correct'],'t1_observation_and_selection_bit_unchanged':t1_after_hashes=={'observation':t1_obs_hash,'selection':t1_sel_hash},'response_content_traceable_no_addition':not response1['added_content'] and not response2['added_content'],'episodic_store_complete':pq.read_table(store).num_rows==len(episodes),'all_required_component_contracts_hashed':len(paths)==23 and all(len(sha(p))==64 for p in paths.values()),'trace_continuous_source_to_outcome':len(trace)==11 and [x['stage'] for x in trace][0]=='t1-observation' and [x['stage'] for x in trace][-1]=='t2-outcome'};assert all(vals.values()),vals
